import{_ as e,o as l,c as s,a2 as a,j as n}from"./chunks/framework.F7eQ-ohH.js";const i="/bzygq/assets/f111c0934ab846d7b818f922e42778a1.DW7AkF_T.png",o="/bzygq/assets/abca0466380f423e81ac7344bb18996c.D9lZCKjO.png",b=JSON.parse('{"title":"Agent执行循环：Planning、Action与Observation","description":"","frontmatter":{},"headers":[],"relativePath":"AI应用开发/四、Agent教程/Agent执行循环：Planning、Action与Observation.md","filePath":"AI应用开发/四、Agent教程/Agent执行循环：Planning、Action与Observation.md","lastUpdated":1788883925000}'),c={name:"AI应用开发/四、Agent教程/Agent执行循环：Planning、Action与Observation.md"};function p(r,t,d,u,g,_){return l(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="agent执行循环-planning、action与observation" tabindex="-1">Agent执行循环：Planning、Action与Observation <a class="header-anchor" href="#agent执行循环-planning、action与observation" aria-label="Permalink to &quot;Agent执行循环：Planning、Action与Observation&quot;">​</a></h1><p>Agent 执行循环是智能体系统的核心运行机制。一个典型 Agent 在每一轮执行中会读取当前任务状态，根据目标生成下一步计划或动作，调用外部工具或请求用户补充信息，再将工具返回结果归一化为 Observation，并据此决定继续执行、结束任务、重试、转人工或中止。</p><p>从系统结构上看，这一过程通常可以概括为 Planning、Action、Observation 和 Policy Control。Planning 负责根据目标和当前状态判断下一步，Action 负责以结构化形式表达工具调用或其他动作，Observation 负责描述工具执行后的结果，Policy Control 则负责权限、风险、步数、超时和终止条件控制。</p><p>因此，Agent 更接近一个带模型决策能力的状态机，而不是普通聊天接口。其工程难点不在多调用几次模型，而在每一轮输入输出是否结构化、工具调用是否可信、状态是否可恢复、失败是否可处理、循环是否可终止。</p><h2 id="从执行链路看-一次-agent-请求长什么样" tabindex="-1">从执行链路看：一次 Agent 请求长什么样 <a class="header-anchor" href="#从执行链路看-一次-agent-请求长什么样" aria-label="Permalink to &quot;从执行链路看：一次 Agent 请求长什么样&quot;">​</a></h2><p>还是用银行 AI 智能客服例子：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户：我的信用卡为什么扣了年费？能不能减免？如果符合条件，帮我生成一段客服回复。</span></span></code></pre></div><p>Agent 内部不是直接回答，而是分几轮执行。第一轮先确认客户和卡片信息，调用 <code>query_customer_profile</code> 得到脱敏客户画像和卡种；第二轮查询扣费交易和消费达标情况，调用 <code>query_card_fee_transaction</code> 得到年费交易和消费次数；第三轮检索业务规则依据，调用 <code>search_bank_policy</code> 得到年费减免规则片段；最后判断材料已经足够，再生成扣费原因、减免判断和客服话术。</p><p>这就是 ReAct 思路的工程化版本：Reasoning 不是展示一堆“思考过程”，而是让模型生成下一步结构化动作；Acting 由后端工具执行；Observation 再回到状态里。</p><h2 id="一、agent-控制循环的基本结构" tabindex="-1">一、Agent 控制循环的基本结构 <a class="header-anchor" href="#一、agent-控制循环的基本结构" aria-label="Permalink to &quot;一、Agent 控制循环的基本结构&quot;">​</a></h2><p>一个可落地的 Agent 循环不是模型自己在脑子里跑，而是由后端系统驱动。</p><p><img src="'+i+'" alt=""></p><p>可以把每一轮拆成 6 个对象：<code>Goal</code> 是用户最终想完成的任务；<code>State</code> 是当前任务状态，包括历史步骤、工具结果、权限和失败次数；<code>Plan</code> 是模型对下一步动作的判断；<code>Action</code> 是结构化动作，可能是调用工具、向用户澄清、结束任务或转人工；<code>Observation</code> 是工具执行或用户补充后得到的新信息；<code>Policy</code> 则是控制规则，决定动作是否允许、是否继续、是否需要人工确认。</p><p>技术上，Agent 循环更像状态机，而不是普通聊天接口。</p><h2 id="二、执行循环伪代码" tabindex="-1">二、执行循环伪代码 <a class="header-anchor" href="#二、执行循环伪代码" aria-label="Permalink to &quot;二、执行循环伪代码&quot;">​</a></h2><p>可以用下面的伪代码理解：</p><p><img src="'+o+`" alt=""></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>state = init_task(user_goal, user_context)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>while state.step_count  觉得不够 -&gt; 换关键词检索 -&gt; 仍觉得不够 -&gt; 再换关键词检索</span></span></code></pre></div><p>可以记录每轮动作签名：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>action_signature = hash(tool_name + normalized_arguments)</span></span></code></pre></div><p>如果同一个工具、同一组核心参数连续出现，且 Observation 没有新增信息，就应该触发停止或让用户补充信息。</p><h2 id="九、一条完整-trace-怎么记录" tabindex="-1">九、一条完整 Trace 怎么记录 <a class="header-anchor" href="#九、一条完整-trace-怎么记录" aria-label="Permalink to &quot;九、一条完整 Trace 怎么记录&quot;">​</a></h2><p>真实项目里，建议把每一次 Agent 执行记录成 Trace。这样出错时能复盘。</p>`,23),n("table",{tabindex:"0"},[n("thead",null,[n("tr",null,[n("th",null,"字段"),n("th",null,"示例")])]),n("tbody",null,[n("tr",null,[n("td",null,"trace_id"),n("td",null,"agent_trace_20260623_001")]),n("tr",null,[n("td",null,"task_id"),n("td",null,"task_10086")]),n("tr",null,[n("td",null,"step_index"),n("td",null,"2")]),n("tr",null,[n("td",null,"prompt_version"),n("td",null,"agent_policy_v3")]),n("tr",null,[n("td",null,"action_type"),n("td",null,"tool_call")]),n("tr",null,[n("td",null,"tool_name"),n("td",null,"search_bank_policy")]),n("tr",null,[n("td",null,"arguments"),n("td",{"query:信用卡白金卡年费减免消费次数":""})]),n("tr",null,[n("td",null,"observation_status"),n("td",null,"success")]),n("tr",null,[n("td",null,"latency_ms"),n("td",null,"842")]),n("tr",null,[n("td",null,"token_in/out"),n("td",null,"1800 / 320")]),n("tr",null,[n("td",null,"decision"),n("td",null,"continue")])])],-1),a(`<p>没有 Trace 的 Agent，出了问题很难排查。你不知道是模型选错工具、参数错、工具返回错，还是最后生成答案时编错。</p><h2 id="十、面试表达模板" tabindex="-1">十、面试表达模板 <a class="header-anchor" href="#十、面试表达模板" aria-label="Permalink to &quot;十、面试表达模板&quot;">​</a></h2><p>可以这样讲：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我会把 Agent 执行流程设计成一个受控循环，而不是让模型自由运行。</span></span>
<span class="line"><span>每一轮系统会把用户目标、当前状态、可用工具和控制策略交给模型，模型只输出结构化 Action。</span></span>
<span class="line"><span>后端先校验 Action，包括工具是否可用、参数是否合法、用户是否有权限，然后再执行工具。</span></span>
<span class="line"><span>工具结果不会原样塞回模型，而是归一化成 Observation，包括摘要、状态、证据和原始数据引用。</span></span>
<span class="line"><span>循环是否继续由终止策略控制，例如最大步数、最大耗时、连续失败、重复动作检测和高风险人审。</span></span></code></pre></div><p>下一篇继续看执行循环里最关键的接口层：Tool Calling 和 Function Calling。</p>`,5)])])}const A=e(c,[["render",p]]);export{b as __pageData,A as default};
